// Каждая проверка читается у своего узла по имени. Если узел упал, в элементе лежит
// ошибка, а не ответ — это и есть признак недоступности сервиса.
const get = (name) => { try { return $(name).item.json; } catch (e) { return null; } };

const voice = get('1a. Голос — whisper и Piper (8088)');
const qdrant = get('1b. Qdrant — векторный поиск (6333)');
const lm     = get('1c. LM Studio — модели в памяти (1234)');
const pg     = get('1d. Postgres — база жива?');

const failed = [];

// 1. Голосовой сервис: распознавание и озвучка живут в одном процессе.
if (!(voice && voice.status === 'ok' && voice.whisper === 'ok'))
  failed.push('голос (whisper + Piper, 8088)');

// 2. Qdrant отвечает текстом, не JSON.
if (!JSON.stringify(qdrant || {}).includes('passed'))
  failed.push('Qdrant — векторный поиск (6333)');

// 3. LM Studio: мало чтобы сервис отвечал — нужные модели должны быть В ПАМЯТИ.
const NEEDED = { 'm15-router-qwen3-4b-lora': 'роутер', 'gemma-4-12b-it-mlx': 'агенты и валидатор',
                 'text-embedding-bge-m3': 'поиск по меню', 'meta/muse-glimmer': 'судья Eval' };
let loaded = [];
if (lm && Array.isArray(lm.data)) {
  loaded = lm.data.filter((m) => m.state === 'loaded').map((m) => m.id);
  const missing = Object.keys(NEEDED).filter((id) => !loaded.includes(id));
  if (missing.length)
    failed.push('модели выгружены из памяти: ' + missing.map((id) => `${id} (${NEEDED[id]})`).join(', '));
} else {
  failed.push('LM Studio — языковые модели (1234)');
}

// 4. База.
if (!(pg && (pg.ok === 1 || pg.ok === '1')))
  failed.push('PostgreSQL — база броней и журнала');

return [{ json: { failed, ok: failed.length === 0, loaded_models: loaded,
                  // Состав сбоев, а не их количество — ключ для дедупликации.
                  state_key: failed.slice().sort().join(' | ') || 'OK' } }];

const cur = $('2. Свести результат проверок').item.json;
const db = $input.first().json || {};
const prev = String(db.last_state || 'OK');
const chat = db.operator_chat_id || null;
const changed = cur.state_key !== prev;

let text = '';
if (changed && !cur.ok) {
  text = '🚨 Сторож «Базилика»: есть проблема\n────────────\n\n'
       + 'Не отвечает или работает неверно:\n— ' + cur.failed.join('\n— ')
       + '\n\nЧто это значит для гостей: '
       + (cur.failed.some((f) => f.includes('PostgreSQL')) ? 'бот не сможет ни ответить, ни записать бронь.'
          : cur.failed.some((f) => f.includes('модели') || f.includes('LM Studio')) ? 'бот перестанет отвечать по существу или начнёт долго думать.'
          : cur.failed.some((f) => f.includes('Qdrant')) ? 'ответы по меню и аллергенам потеряют опору на базу знаний.'
          : 'голосовые сообщения не будут распознаваться и озвучиваться, текст работает.')
       + '\n\nПроверка каждые 10 минут. Следующее сообщение придёт, когда состав сбоев изменится.';
} else if (changed && cur.ok) {
  text = '✅ Сторож «Базилика»: всё восстановлено\n────────────\n\n'
       + 'Было: ' + prev + '\nСейчас все четыре службы отвечают, нужные модели в памяти.';
}

return [{ json: { ...cur, prev_state: prev, changed, operator_chat_id: chat, alert_text: text } }];

const e = $input.first().json || {};
const wf = e.workflow || {};
const ex = e.execution || {};
const node = ex.lastNodeExecuted || 'неизвестен';
const msg = String(ex.error?.message || e.message || 'без текста').split('\n')[0].slice(0, 300);

const text = '⚠️ Прогон упал\n────────────\n\n'
  + 'Граф: ' + (wf.name || 'неизвестен') + '\n'
  + 'Узел: ' + node + '\n'
  + 'Ошибка: ' + msg + '\n'
  + (ex.id ? 'Выполнение № ' + ex.id + '\n' : '')
  + (ex.url ? ex.url + '\n' : '')
  + '\nГость мог не получить ответ — проверьте переписку.';

return [{ json: { text } }];
